text:
{
  "questions": [
    {
      "n": 1,
      "start": "Strategien und Massnahmen: Welche konkreten Strategien",
      "end": "verfolgt der Kanton Bern, um das Recycling von EPS zu fördern?"
    },
    {
      "n": 2,
      "start": "Zusammenarbeit mit Akteuren: Wie arbeitet der Kanton Bern",
      "end": "mit Akteuren wie Recyclingunternehmen, Bauunternehmen und Verbänden zusammen, um die Sammlung und Wiederverwertung von EPS zu optimieren?"
    },
    {
      "n": 3,
      "start": "Sensibilisierung und Information: Welche Massnahmen ergreift",
      "end": "die Verwaltung, um Bauherren, Architekten, Verwaltungen und Unternehmen über die Möglichkeiten und Vorteile des EPS-Recyclings zu informieren?"
    },
    {
      "n": 4,
      "start": "Rechtliche Rahmenbedingungen: Sind Anpassungen der kantonalen",
      "end": "Vorschriften geplant oder bereits umgesetzt, um das Recycling von EPS zu erleichtern oder gar verpflichtend zu machen?"
    },
    {
      "n": 5,
      "start": "Erfolgsmessung: Wie misst der Kanton den Erfolg seiner Bemühungen",
      "end": "im Bereich des Baustoff-Recyclings, insbesondere bei EPS? Gibt es Zielvorgaben oder Kennzahlen zur Erhöhung der Recyclingquote bei EPS?"
    },
    {
      "n": 6,
      "start": "Vorbildfunktion des Kantons: Inwiefern setzt der Kanton Bern bei",
      "end": "eigenen Bauprojekten auf recycelte EPS-Dämmstoffe oder andere nachhaltige Materialien?"
    }
  ],
  "answers": [
    {
      "n": 1,
      "start": "Der Kanton Bern hat bisher keine Recyclingquote für EPS erhoben.",
      "end": "Eine rein bernische Strategie erscheint nicht zielführend, da der Markt für die nötigen Investitionen zu klein wäre."
    },
    {
      "n": 2,
      "start": "Einzelkantone haben tendenziell gegenüber den Branchenakteuren wenig Gewicht.",
      "end": "Der Kanton Bern bringt sich deshalb in nationalen Gremien wie dem Cercle déchets Schweiz, der Konferenz der Umweltämter der Schweiz (KVU) und dem Bundesamt für Umwelt (BAFU) ein."
    },
    {
      "n": 3,
      "start": "Der Kanton Bern wird entsprechende Informationen und allfällige Sensibilisierungskampagnen ins Auge fassen,",
      "end": "sobald sich ein funktionierender Recyclingmarkt, respektive industrietaugliche Verfahren zur Ausschleusung der Schadstoffe abzeichnen und die Schadstoffproblematik durch einen getrennten Rückbau der Dämmstoffe sichergestellt werden kann."
    },
    {
      "n": 4,
      "start": "Die regulatorischen Massnahmen zur Erreichung der Ziele sind in den nationalen Verordnungen wie beispielsweise der Verordnung vom 4. Dezember 2015 über die Vermeidung und die Entsorgung von Abfällen (Abfallverordnung, VVEA; SR 814.600) vorzusehen.",
      "end": "Der Regierungsrat erachtet daher kantonale Vorschriften nicht als zielführend."
    },
    {
      "n": 5,
      "start": "Der Kanton Bern hat bisher keine Recyclingquote für EPS erhoben.",
      "end": "Diese Zahlen zu ermitteln ist schwierig und wäre mit vielen Unsicherheiten behaftet."
    },
    {
      "n": 6,
      "start": "Der Kanton Bern hält sich beim Rückbau eigener Immobilien oder eigenen Bauprojekten an die strikte Anwendung von Nachhaltigkeitskriterien in allen Belangen.",
      "end": "Vorschriften explizit in Bezug auf EPS-Recycling bestehen hingegen noch nicht, werden aber geprüft, sobald in Abstimmung mit dem Bund regulatorische Massnahmen angezeigt sind."
    }
  ],
  "submitter": "Lüthi (Moosseedorf, GLP)",
  "co_signatories": [],
  "recommendation": "none",
  "reasoning": {
    "start": "In den letzten Jahren wurden von der Recyclingbranche immer wieder Versuche unternommen, Verfahren zur Entfrachtung von HBCD zu entwickeln.",
    "end": "Bisher gibt es aber keine funktionierende Anlage im industriellen Massstab."
  }
}
